  function rankingPage(){
    const c=client(),rankingChannel=c.rankChannel||'bol',rankingCountry=c.rankCountry||'NL',days=c.rankDays||7;
    const keywords=p=>c['keywords-'+p.sku]||CD.keywords(state(),p.sku,rankingCountry);
    const readings=p=>{
      const words=keywords(p),known=p.rank!==null||Boolean(c['keywords-'+p.sku]);
      const offset=D.channels.findIndex(ch=>ch.id===rankingChannel)*2;
      const position=known?words[0].position+offset:null;
      // Fixed fictional comparisons for each lookback; never a live ranking measurement.
      const change=known?(words[0].previous-words[0].position)*(tab==='movers'?(days===90?3:days===30?2:1):1):null;
      return {position,change};
    };
    const movement=n=>`<span class="ranking-change ${n===null||n===0?'is-steady':n>0?'is-rise':'is-fall'}">${n===null?'—':n===0?'→ 0':(n>0?'↑ ':'↓ ')+number(Math.abs(n))}</span>`;
    const identity=p=>{const i=state().products.indexOf(p),rating=[4,5,3,4,5,4][i%6],reviews=[54,38,12,27,76,43][i%6];return `<span class="ranking-product"><span class="ranking-photo">${host.thumb(p.sku)}</span><span class="ranking-product-copy"><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(rankingChannel==='bol'?rankingCountry:D.channels.find(ch=>ch.id===rankingChannel).country)} ${badge(p.classification,p.classification==='A'?'good':p.classification==='B'?'warning':'bad')}</small><span class="ranking-reviews" aria-label="${rating} / 5 (${reviews})"><span aria-hidden="true">${'★'.repeat(rating)}<span class="ranking-empty-stars">${'☆'.repeat(5-rating)}</span></span><small>(${reviews})</small></span></span></span>`;};
    const detail=p=>table(['Zoekwoord','Positie','Vorige positie','Voorbeeldvolume'],keywords(p).map(w=>[esc(w.term),badge(p.rank===null&&!c['keywords-'+p.sku]?'—':'#'+(w.position+D.channels.findIndex(ch=>ch.id===rankingChannel)*2),w.position<=10?'good':'warning'),p.previousRank===null?'—':number(w.previous+D.channels.findIndex(ch=>ch.id===rankingChannel)*2),number(w.volume)]))+`<div class="workspace-actions">${button('Artikelkaart','article',p.sku,'','box')}</div>`+details('Zoekwoorden aanpassen',form('keywords',`<input type="hidden" name="sku" value="${p.sku}">`+textarea('Tien zoekwoorden, één per regel','terms',keywords(p).map(w=>w.term).join('\n')),'Zoekwoorden in demo bewaren','search'));
    const row=(p,mover=false)=>{const {position,change}=readings(p);return `<article class="ranking-item" data-ranking-sku="${esc(p.sku)}"><details class="workspace-details ranking-detail"${tab==='keywords'?' open':''}><summary>${identity(p)}<span class="ranking-result"><strong>${position===null?'—':'#'+position}</strong>${movement(change)}${!mover?`<span class="ranking-word-count">${number(keywords(p).length)} <span>Zoekwoorden</span></span>`:''}</span></summary><div>${detail(p)}</div></details>${mover?`<div class="ranking-row-actions">${button('Ranking','rank-focus',p.sku,'','chart')}${button('Uitsluiten','rank-exclude',p.sku,'is-danger','alert')}${button('Gelezen','rank-read',p.sku,'','check')}</div>`:''}</article>`;};
    const header=`<header class="ranking-heading"><div>${tab==='movers'?`<span class="ranking-heading-icons"><span class="is-rise">${icon('chart')}</span><span class="is-fall">${icon('chart')}</span></span>`:`<img src="${esc(D.channels.find(ch=>ch.id===rankingChannel).logo)}" alt="${esc(D.channels.find(ch=>ch.id===rankingChannel).label)}">`}<h1>Productranking</h1></div><span class="ranking-demo-label">Fictieve gegevens</span></header>`;
    const tabs='<nav class="workspace-tabs ranking-view-tabs" aria-label="Paginaweergaven">'+C.pages['bol-ranking'].tabs.map(t=>`<button type="button" data-full-tab="${t.id}" aria-current="${tab===t.id?'page':'false'}">${esc(t.label)}</button>`).join('')+'</nav>';
    let items=state().products.filter(p=>!query||[p.name,p.sku,p.ean,...keywords(p).map(w=>w.term)].join(' ').toLowerCase().includes(query.toLowerCase()));
    lastExport=[['Artikel','Ranking','Verschil'],...items.map(p=>{const r=readings(p);return [p.name,r.position??'',r.change??''];})];
    if(tab==='movers'){
      items=items.filter(p=>readings(p).change!==null&&!c.rankingExcluded?.includes(p.sku)&&!c.rankingRead?.includes(p.sku));
      const section=(title,list)=>`<section class="ranking-mover-group"><h2>${esc(title)} <small>(${number(list.length)})</small></h2>${list.map(p=>row(p,true)).join('')||'<p class="workspace-note">Geen artikelen in deze weergave.</p>'}</section>`;
      return `<section class="ranking-screen">${header}${tabs}<nav class="workspace-subtabs ranking-periods" aria-label="Vergelijkingsperiode">${[7,30,90].map(n=>`<button type="button" data-w-action="rank-period" data-id="${n}" aria-pressed="${days===n}">${n} <span>dagen</span></button>`).join('')}</nav><p class="ranking-stamp">Voorbeeldmeting · <span>27-10-2026</span> · ${days} <span>dagen</span></p><div class="ranking-mover-columns">${section('Dalers',items.filter(p=>readings(p).change<0))}${section('Stijgers',items.filter(p=>readings(p).change>0))}</div></section>`;
    }
    const sort=c.rankSort||'position';items.sort((a,b)=>sort==='article'?a.name.localeCompare(b.name):sort==='change'?(readings(b).change??-999)-(readings(a).change??-999):(readings(a).position??999)-(readings(b).position??999));
    const channels=`<nav class="workspace-subtabs ranking-channels" aria-label="Verkoopkanaal">${D.channels.map(ch=>`<button type="button" data-w-action="rank-channel" data-id="${ch.id}" aria-pressed="${rankingChannel===ch.id}">${esc(ch.label)}</button>`).join('')}</nav>`;
    const controls=`<form class="ranking-search" data-w-form="rank-search"><label class="workspace-field">Zoeken in ranking<input name="query" type="search" value="${esc(query)}" placeholder="SKU, EAN, artikel of zoekwoord" maxlength="150"></label><button class="workspace-button is-orange" type="submit">${icon('search')}Zoeken</button></form>`;
    return `<section class="ranking-screen">${header}${tabs}${channels}${controls}<div class="ranking-columns">${[['article','Artikel'],['position','Ranking'],['change','Verschil']].map(([id,label])=>`<button type="button" data-w-action="rank-sort" data-id="${id}" aria-pressed="${sort===id}">${esc(label)} <span aria-hidden="true">${sort===id?'↑':'⇅'}</span></button>`).join('')}</div><div class="ranking-products">${items.map(p=>row(p)).join('')||'<p class="workspace-note">Geen artikelen in deze weergave.</p>'}</div><div class="ranking-secondary-controls">${form('rank-country',select('Rankingland','country',['NL','BE'],rankingCountry),'Land bekijken','globe')}${button('Voorbeeldmeting uitvoeren','rank-measure','','','search')}</div></section>`;
  }
