    if(page==='publicaties')return panel('Publicatiestatus per artikel en kanaal',products().map(p=>details(`${productLink(p)}${badge(p.offers.filter(s=>s==='failed').length+' fouten',p.offers.includes('failed')?'bad':'good')}`,table(['Kanaal','Status','Controle'],D.channels.map((ch,i)=>[brand(ch.id),badge({published:'Gepubliceerd',queued:'Wachtrij',failed:'Kenmerk ontbreekt',disabled:'Niet gepubliceerd'}[p.offers[i]],p.offers[i]==='failed'?'bad':p.offers[i]==='published'?'good':'warning'),hostButton('Offer bekijken','offers',p.sku)])))).join(''));
    if(page==='media')return panel('Productmedia',`<div class="workspace-media-grid">${products().map(p=>`<article><figure>${host.svg(p.sku,0)}<figcaption>${esc(p.name)}</figcaption></figure>${badge(p.contentApproved?'Beoordeeld':'Te beoordelen',p.contentApproved?'good':'warning')}<div class="workspace-actions">${button('Beeld controleren','media-approve',p.sku)}${button('Download SVG','media-download',p.sku,'','download')}</div></article>`).join('')}</div>`);
    if(page==='handleidingen')return panel('Nederlandse handleiding maken',form('manual',select('Artikel','sku',productOptions(),selection)+textarea('Voorbeeldtekst uit de leveranciershandleiding','source','Product installation guide. Check the components, connect according to the installation instructions and test the product before use.'),'Voorbeeldhandleiding maken','file'))+panel('Handleidingen per artikel',c.manuals.map(m=>details(`<span>${icon('file')} ${esc(m.title)}</span>${badge(m.status,m.status==='Goedgekeurd'?'good':'warning')}`,form('manual-edit',`<input type="hidden" name="id" value="${m.id}">`+textarea('Nederlandse handleiding','text',m.text),'Wijzigingen bewaren','file')+`<div class="workspace-actions">${button('Goedkeuren','manual-approve',m.id)}${button('Download tekst','manual-download',m.id,'','download')}</div>`)).join(''));
    const isEnrich=tab==='data-verrijken',list=tab==='concepten'||(page==='ai-assistant'&&tab==='concepten');
    if(list)return panel('Je productconcepten',table(['Concept','Artikel','Status','Actie'],c.drafts.map(d=>[esc(d.id),esc(d.name),badge(d.status,d.status==='Goedgekeurd'?'good':'warning'),button('Bewerken / beoordelen','draft',d.id,'','file')])));
    if(page==='ai-assistant'&&tab==='checks')return panel('Productcontroles',table(['Artikel','Listingkwaliteit','Beelden','Controle'],products().map(p=>[productLink(p),badge(p.listing+'/100',p.listing>=85?'good':'warning'),badge(p.contentApproved?'Beoordeeld':'Nog beoordelen',p.contentApproved?'good':'warning'),hostButton('Controle bekijken','listing',p.sku)])));
