    return panel(isEnrich?'Bestaand artikel verrijken':'Nieuw productconcept',form('product-draft',(isEnrich?select('Bestaand artikel','sku',productOptions(),selection):field('Productnaam','name',exampleText('Draagbare speaker Nova'),'text','maxlength="150" required'))+field('Merk','brand','Nova')+textarea('Broninformatie / productkenmerken','features',exampleText('Compacte speaker voor dagelijks gebruik. Voeg alleen gecontroleerde productkenmerken toe.'))+select('Schrijfstijl','style',['Duidelijk en praktisch','Kort en zakelijk']),'Voorbeeldconcept samenstellen','signal'))+panel('Werkwijze','<ol><li>Verzamel productkenmerken en broninformatie.</li><li>Maak een concept met titel, beschrijving en kenmerken.</li><li>Controleer het concept en keur het zelf goed.</li></ol><p>Deze demonstratie gebruikt vaste voorbeeldteksten en verstuurt geen AI-aanvragen.</p>');
